int partition(vector<int>& nums, int l, int r) {
  int pivot = nums[r]; int i = l;
  for (int j=l;j<r;++j) if (nums[j] <= pivot) swap(nums[i++], nums[j]);
  swap(nums[i], nums[r]);
  return i;
}
int findKthLargest(vector<int>& nums, int k) {
  int l=0, r=nums.size()-1, target = nums.size()-k;
  while (l<=r) {
    int idx = partition(nums,l,r);
    if (idx==target) return nums[idx];
    else if (idx<target) l=idx+1; else r=idx-1;
  }
  return -1;
}

class Solution {
  public int findKthLargest(int[] nums, int k) {
    int l=0, r=nums.length-1, target = nums.length-k;
    while (l<=r) {
      int p = partition(nums,l,r);
      if (p==target) return nums[p];
      else if (p<target) l=p+1; else r=p-1;
    }
    return -1;
  }
  private int partition(int[] nums,int l,int r) {
    int pivot = nums[r], i=l;
    for (int j=l;j<r;j++) if (nums[j] <= pivot) swap(nums,i++,j);
    swap(nums,i,r); return i;
  }
}

