  }
}

function reverseKGroup(head, k) {
  const dummy = { next: head };
  let prevGroup = dummy;
  while (true) {
    let kth = prevGroup;
    for (let i = 0; i < k && kth; i++) kth = kth.next;
    if (!kth) break;
    let groupNext = kth.next;
    let prev = groupNext, curr = prevGroup.next;
    while (curr !== groupNext) {
      const tmp = curr.next; curr.next = prev; prev = curr; curr = tmp;
    }
    const tmp = prevGroup.next; prevGroup.next = kth; prevGroup = tmp;
  }
  return dummy.next;
}

ListNode* reverseKGroup(ListNode* head, int k) {
  ListNode dummy(0); dummy.next = head; ListNode* prevGroup = &dummy;
  while (true) {
    ListNode* kth = prevGroup;
    for (int i=0;i<k && kth;i++) kth = kth->next;
    if (!kth) break;
    ListNode* groupNext = kth->next;
    ListNode* prev = groupNext; ListNode* curr = prevGroup->next;
    while (curr != groupNext) {
      ListNode* nxt = curr->next; curr->next = prev; prev = curr; curr = nxt;
    }
    ListNode* tmp = prevGroup->next; prevGroup->next = kth; prevGroup = tmp;
  }
  return dummy.next;
}

class Solution {
  public ListNode reverseKGroup(ListNode head, int k) {
    ListNode dummy = new ListNode(0); dummy.next = head; ListNode prevGroup = dummy;
    while (true) {
      ListNode kth = prevGroup;
      for (int i=0;i<k && kth!=null;i++) kth = kth.next;
      if (kth == null) break;
      ListNode groupNext = kth.next;
      ListNode prev = groupNext, curr = prevGroup.next;
      while (curr != groupNext) {
        ListNode nxt = curr.next; curr.next = prev; prev = curr; curr = nxt;
      }
      ListNode tmp = prevGroup.next; prevGroup.next = kth; prevGroup = tmp;
    }
    return dummy.next;
  }
}

function copyRandomList(head) {
  if (!head) return null;
