  while (curr) {
    const copy = { val: curr.val, next: curr.next, random: null };
    curr.next = copy;
    curr = copy.next;
  }
  curr = head;
  while (curr) { if (curr.random) curr.next.random = curr.random.next; curr = curr.next.next; }
  curr = head; const pseudoHead = { next: head.next };
  while (curr) { const copy = curr.next; curr.next = copy.next; copy.next = copy.next ? copy.next.next : null; curr = curr.next; }
  return pseudoHead.next;
}

