  const split = (head) => { let slow = head, fast = head, prev = null; while (fast && fast.next) { prev = slow; slow = slow.next; fast = fast.next.next; } prev.next = null; return slow; };
  const merge = (a, b) => { const dummy = { next: null }; let tail = dummy; while (a && b) { if (a.val < b.val) { tail.next = a; a = a.next; } else { tail.next = b; b = b.next; } tail = tail.next; } tail.next = a || b; return dummy.next; };
  const mid = split(head); return merge(sortList(head), sortList(mid));
