function solveSudoku(board) {
  const rows = Array.from({length:9}, () => new Set());
  const cols = Array.from({length:9}, () => new Set());
  const boxes = Array.from({length:9}, () => new Set());
  const empties = [];
  for (let r=0;r<9;r++) {
    for (let c=0;c<9;c++) {
      const v = board[r][c];
      if (v !== '.') {
        rows[r].add(v);
        cols[c].add(v);
        boxes[Math.floor(r/3)*3 + Math.floor(c/3)].add(v);
      } else {
        empties.push([r,c]);
      }
    }
  }
  const dfs = (i) => {
    if (i === empties.length) return true;
    const [r,c] = empties[i];
    const b = Math.floor(r/3)*3 + Math.floor(c/3);
    for (let d = 1; d <= 9; d++) {
      const ch = String(d);
      if (!rows[r].has(ch) && !cols[c].has(ch) && !boxes[b].has(ch)) {
        board[r][c] = ch;
        rows[r].add(ch);
        cols[c].add(ch);
        boxes[b].add(ch);
        if (dfs(i+1)) return true;
        board[r][c] = '.';
        rows[r].delete(ch);
        cols[c].delete(ch);
        boxes[b].delete(ch);
      }
    }
    return false;
  };
  dfs(0);
}

