function minCut(s) {
  const n = s.length;
  const pali = Array.from({length:n}, ()=>Array(n).fill(false));
  for (let i=n-1;i>=0;i--) {
    for (let j=i;j<n;j++) {
      pali[i][j] = (s[i]===s[j]) && (j-i<2 || pali[i+1][j-1]);
    }
  }
  const dp = Array(n+1).fill(Infinity); dp[0] = -1;
  for (let i=1;i<=n;i++) {
    for (let j=0;j<i;j++) {
      if (pali[j][i-1]) dp[i] = Math.min(dp[i], dp[j] + 1);
    }
  }
  return dp[n];
}

