class Solution {
  public int minCut(String s) {
    int n = s.length();
    boolean[][] pali = new boolean[n][n];
    for (int i=n-1;i>=0;i--) {
      for (int j=i;j<n;j++) {
        pali[i][j] = s.charAt(i)==s.charAt(j) && (j-i<2 || pali[i+1][j-1]);
      }
    }
    int[] dp = new int[n+1];
    Arrays.fill(dp, 1_000_000); dp[0] = -1;
    for (int i=1;i<=n;i++) for (int j=0;j<i;j++) if (pali[j][i-1]) dp[i] = Math.min(dp[i], dp[j]+1);
    return dp[n];
  }
}

