      count += right - left;
    }
    return count;
  };
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (countPairs(mid) >= k) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

