def findLadders(beginWord, endWord, wordList):
    wordSet = set(wordList)
    if endWord not in wordSet: return []
    # BFS to build adjacency by level
    layer = {beginWord: [[beginWord]]}
    while layer:
        newLayer = defaultdict(list)
        for word in layer:
            if word == endWord:
                return layer[word]
        for word in layer:
            for i in range(len(word)):
                for c in 'abcdefghijklmnopqrstuvwxyz':
                    newWord = word[:i] + c + word[i+1:]
                    if newWord in wordSet:
                        newLayer[newWord] += [path + [newWord] for path in layer[word]]
        wordSet -= set(newLayer.keys())
        layer = newLayer
    return []

function findLadders(beginWord, endWord, wordList) {
  const wordSet = new Set(wordList);
  if (!wordSet.has(endWord)) return [];
  let layer = new Map([[beginWord, [[beginWord]]]]);
  while (layer.size) {
    const newLayer = new Map();
    for (const [word, paths] of layer.entries()) {
      if (word === endWord) return paths;
    }
    for (const [word, paths] of layer.entries()) {
      for (let i = 0; i < word.length; i++) {
        for (let c = 97; c <= 122; c++) {
          const newWord = word.slice(0,i) + String.fromCharCode(c) + word.slice(i+1);
          if (wordSet.has(newWord)) {
            const arr = newLayer.get(newWord) || [];
            for (const p of paths) arr.push(p.concat([newWord]));
            newLayer.set(newWord, arr);
          }
        }
      }
    }
    for (const k of newLayer.keys()) wordSet.delete(k);
    layer = newLayer;
  }
  return [];
}

