vector<vector<string>> findLadders(string beginWord, string endWord, vector<string>& wordList) {
    unordered_set<string> dict(wordList.begin(), wordList.end());
    vector<vector<string>> res;
    if (!dict.count(endWord)) return res;
    unordered_map<string, vector<vector<string>>> layer;
    layer[beginWord] = {{beginWord}};
    while (!layer.empty()) {
        unordered_map<string, vector<vector<string>>> newLayer;
        for (auto &p : layer) {
            const string &word = p.first;
            if (word == endWord) {
                for (auto &path : p.second) res.push_back(path);
            }
        }
        if (!res.empty()) return res;
        for (auto &p : layer) {
            const string &word = p.first;
            for (int i = 0; i < word.size(); ++i) {
                string newWord = word;
                for (char c = 'a'; c <= 'z'; ++c) {
                    newWord[i] = c;
                    if (dict.count(newWord)) {
                        for (auto path : p.second) {
                            path.push_back(newWord);
                            newLayer[newWord].push_back(path);
                        }
                    }
                }
            }
        }
        for (auto &it : newLayer) dict.erase(it.first);
        layer.swap(newLayer);
    }
    return res;
}

