def maxAreaOfIsland(grid):
    m, n = len(grid), len(grid[0])
    visited = [[False]*n for _ in range(m)]
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    def dfs(i, j):
        if i<0 or i>=m or j<0 or j>=n or grid[i][j]==0 or visited[i][j]:
            return 0
        visited[i][j] = True
        area = 1
        for di, dj in dirs:
            area += dfs(i+di, j+dj)
        return area
    ans = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1 and not visited[i][j]:
                ans = max(ans, dfs(i, j))
    return ans

