        int ans = 0;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 1) ans = max(ans, dfs(grid, i, j));
            }
        }
        return ans;
    }
private:
    int dfs(vector<vector<int>>& grid, int i, int j) {
        int m = grid.size(), n = grid[0].size();
        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0) return 0;
        grid[i][j] = 0; // mark visited
        int area = 1;
        area += dfs(grid, i+1, j);
        area += dfs(grid, i-1, j);
        area += dfs(grid, i, j+1);
        area += dfs(grid, i, j-1);
        return area;
    }
};

class Solution {
  public int maxAreaOfIsland(int[][] grid) {
    int m = grid.length, n = grid[0].length, ans = 0;
    for (int i = 0; i < m; i++)
      for (int j = 0; j < n; j++)
        if (grid[i][j] == 1) ans = Math.max(ans, dfs(grid, i, j));
    return ans;
  }
  private int dfs(int[][] grid, int i, int j) {
    int m = grid.length, n = grid[0].length;
    if (i<0||i>=m||j<0||j>=n||grid[i][j]==0) return 0;
    grid[i][j] = 0;
    return 1 + dfs(grid,i+1,j) + dfs(grid,i-1,j) + dfs(grid,i,j+1) + dfs(grid,i,j-1);
  }
}

def pacificAtlantic(heights):
    if not heights: return []
    m, n = len(heights), len(heights[0])
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    def dfs(starts):
        reachable = [[False]*n for _ in range(m)]
        stack = starts[:]
        while stack:
            i, j = stack.pop()
            reachable[i][j] = True
            for di, dj in dirs:
                ni, nj = i+di, j+dj
                if 0<=ni<m and 0<=nj<n and not reachable[ni][nj] and heights[ni][nj] >= heights[i][j]:
                    stack.append((ni, nj))
        return reachable
    pac = dfs([(i,0) for i in range(m)] + [(0,j) for j in range(n)])
    atl = dfs([(i,n-1) for i in range(m)] + [(m-1,j) for j in range(n)])
    res = []
    for i in range(m):
        for j in range(n):
            if pac[i][j] and atl[i][j]: res.append([i,j])
    return res

function pacificAtlantic(heights) {
  if (!heights || !heights.length) return [];
  const m = heights.length, n = heights[0].length;
  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
  function dfs(starts) {
    const reachable = Array.from({length:m}, () => Array(n).fill(false));
    const stack = starts.slice();
    while (stack.length) {
      const [i,j] = stack.pop();
      reachable[i][j] = true;
      for (const [di,dj] of dirs) {
        const ni = i+di, nj = j+dj;
        if (ni>=0 && ni<m && nj>=0 && nj<n && !reachable[ni][nj] && heights[ni][nj] >= heights[i][j]) {
          stack.push([ni,nj]);
        }
      }
    }
    return reachable;
  }
  const pac = dfs([...Array(m).keys()].map(i=>[i,0]).concat([...Array(n).keys()].map(j=>[0,j])));
  const atl = dfs([...Array(m).keys()].map(i=>[i,n-1]).concat([...Array(n).keys()].map(j=>[m-1,j])));
  const res = [];
  for (let i=0;i<m;i++) for (let j=0;j<n;j++) if (pac[i][j] && atl[i][j]) res.push([i,j]);
  return res;
}

