        return image;
    }
private:
    void dfs(vector<vector<int>>& img, int i, int j, int orig, int nc) {
        int m = img.size(), n = img[0].size();
        if (i<0||i>=m||j<0||j>=n||img[i][j] != orig) return;
        img[i][j] = nc;
        dfs(img, i+1, j, orig, nc);
        dfs(img, i-1, j, orig, nc);
        dfs(img, i, j+1, orig, nc);
        dfs(img, i, j-1, orig, nc);
    }
};

