    def partition(left, right):
        pivot = missing[right]
        i = left

        for j in range(left, right):
            if missing[j] <= pivot:
                missing[i], missing[j] = missing[j], missing[i]
                i += 1

        missing[i], missing[right] = missing[right], missing[i]
        return i

    return quick_select(0, len(missing) - 1, k - 1)

var arrayPairSum = function(nums) {
    const quickSelect = (left, right, kth) => {
        if (left === right) return;

        const pivotIndex = partition(left, right);

        if (kth === pivotIndex) {
            return;
        } else if (kth < pivotIndex) {
            quickSelect(left, pivotIndex - 1, kth);
        } else {
            quickSelect(pivotIndex + 1, right, kth);
        }
    };

    const partition = (left, right) => {
        const pivot = nums[right];
        let i = left;

        for (let j = left; j < right; j++) {
            if (nums[j] <= pivot) {
                [nums[i], nums[j]] = [nums[j], nums[i]];
                i++;
            }
        }

        [nums[i], nums[right]] = [nums[right], nums[i]];
        return i;
    };

    for (let i = 0; i < nums.length / 2; i++) {
        quickSelect(i, nums.length - 1, i);
    }

    let sum = 0;
    for (let i = 0; i < nums.length; i += 2) {
        sum += nums[i];
    }

    return sum;
};

def arrayPairSum(nums):
    def quick_select(left, right, k_smallest):
        if left == right:
            return

        pivot_index = partition(left, right)

        if k_smallest == pivot_index:
            return
        elif k_smallest < pivot_index:
            quick_select(left, pivot_index - 1, k_smallest)
        else:
            quick_select(pivot_index + 1, right, k_smallest)

    def partition(left, right):
        pivot = nums[right]
        i = left

        for j in range(left, right):
            if nums[j] <= pivot:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1

        nums[i], nums[right] = nums[right], nums[i]
        return i

    for i in range(len(nums) // 2):
        quick_select(i, len(nums) - 1, i)

    total = 0
    for i in range(0, len(nums), 2):
        total += nums[i]

    return total

