var relativeSortArray = function(arr1, arr2) {
    const orderMap = new Map();

    for (let i = 0; i < arr2.length; i++) {
        orderMap.set(arr2[i], i);
    }

    arr1.sort((a, b) => {
        const hasA = orderMap.has(a);
        const hasB = orderMap.has(b);

        if (hasA && hasB) {
            return orderMap.get(a) - orderMap.get(b);
        } else if (hasA) {
            return -1;
        } else if (hasB) {
            return 1;
        } else {
            return a - b;
        }
    });

    return arr1;
};

class Solution:
    def relativeSortArray(self, arr1: List[int], arr2: List[int]) -> List[int]:
        order_map = {num: i for i, num in enumerate(arr2)}

        def custom_sort(x):
            if x in order_map:
                return (0, order_map[x])
            else:
                return (1, x)

        arr1.sort(key=custom_sort)
        return arr1

class Solution {
public:
    vector<int> relativeSortArray(vector<int>& arr1, vector<int>& arr2) {
        unordered_map<int, int> orderMap;
        for (int i = 0; i < arr2.size(); i++) {
            orderMap[arr2[i]] = i;
        }

        sort(arr1.begin(), arr1.end(), [&](int a, int b) {
            bool hasA = orderMap.count(a);
            bool hasB = orderMap.count(b);

            if (hasA && hasB) {
                return orderMap[a] < orderMap[b];
            } else if (hasA) {
                return true;
            } else if (hasB) {
                return false;
            } else {
                return a < b;
            }
        });

        return arr1;
    }
};

class Solution {
    public int[] relativeSortArray(int[] arr1, int[] arr2) {
        Map<Integer, Integer> orderMap = new HashMap<>();
        for (int i = 0; i < arr2.length; i++) {
            orderMap.put(arr2[i], i);
        }

        List<Integer> list = new ArrayList<>();
        for (int num : arr1) {
            list.add(num);
        }

        list.sort((a, b) -> {
            boolean hasA = orderMap.containsKey(a);
            boolean hasB = orderMap.containsKey(b);

            if (hasA && hasB) {
                return orderMap.get(a) - orderMap.get(b);
            } else if (hasA) {
                return -1;
            } else if (hasB) {
                return 1;
            } else {
                return a - b;
            }
        });

        return list.stream().mapToInt(i -> i).toArray();
    }
}

var minDistance = function(word1, word2) {
    const m = word1.length;
    const n = word2.length;
    const dp = Array(m + 1).fill().map(() => Array(n + 1).fill(0));

    for (let i = 0; i <= m; i++) {
        dp[i][0] = i;
    }
    for (let j = 0; j <= n; j++) {
        dp[0][j] = j;
    }

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            if (word1[i - 1] === word2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = Math.min(
                    dp[i - 1][j - 1], // replace
                    dp[i - 1][j],     // delete
                    dp[i][j - 1]      // insert
                ) + 1;
            }
        }
    }

    return dp[m][n];
};

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m, n = len(word1), len(word2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(m + 1):
            dp[i][0] = i
        for j in range(n + 1):
            dp[0][j] = j

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if word1[i - 1] == word2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    dp[i][j] = min(
                        dp[i - 1][j - 1],  # replace
                        dp[i - 1][j],      # delete
                        dp[i][j - 1]       # insert
                    ) + 1

        return dp[m][n]

