var largestPalindrome = function(n) {
    if (n === 1) return 9;

    const upper = Math.pow(10, n) - 1;
    const lower = Math.pow(10, n - 1);

    for (let i = upper; i >= lower; i--) {
        const palindrome = BigInt(i) * BigInt(Math.pow(10, n) + BigInt(1)) - BigInt(i) * BigInt(1);

        for (let j = upper; j >= lower; j--) {
            if (BigInt(j) * BigInt(j) < palindrome) break;
            if (palindrome % BigInt(j) === BigInt(0)) {
                return Number(palindrome % 1337n);
            }
        }
    }

    return -1;
};

class Solution:
    def largestPalindrome(self, n: int) -> int:
        if n == 1:
            return 9

        upper = 10**n - 1
        lower = 10**(n-1)

        for i in range(upper, lower - 1, -1):
            palindrome = int(str(i) + str(i)[::-1])

            j = upper
            while j * j >= palindrome:
                if palindrome % j == 0:
                    return palindrome % 1337
                j -= 1

        return -1

var isRobotBounded = function(instructions) {
    let x = 0, y = 0;
    let dir = 0; // 0: north, 1: east, 2: south, 3: west
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];

    for (let instruction of instructions) {
        if (instruction === 'G') {
            x += directions[dir][0];
            y += directions[dir][1];
        } else if (instruction === 'L') {
            dir = (dir + 3) % 4; // turn left
        } else if (instruction === 'R') {
            dir = (dir + 1) % 4; // turn right
        }
    }

    return (x === 0 && y === 0) || dir !== 0;
};

class Solution:
