        x, y = 0, 0
        dir = 0  # 0: north, 1: east, 2: south, 3: west
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        for instruction in instructions:
            if instruction == 'G':
                x += directions[dir][0]
                y += directions[dir][1]
            elif instruction == 'L':
                dir = (dir + 3) % 4
            elif instruction == 'R':
                dir = (dir + 1) % 4

        return (x == 0 and y == 0) or dir != 0

var maxRotateFunction = function(nums) {
    const n = nums.length;
    let sum = 0;
    let f = 0;

    for (let i = 0; i < n; i++) {
        sum += nums[i];
        f += i * nums[i];
    }

    let maxF = f;

    for (let i = n - 1; i > 0; i--) {
        f = f + sum - n * nums[i];
        maxF = Math.max(maxF, f);
    }

    return maxF;
};

class Solution:
