var minFlips = function(s) {
    const n = s.length;
    let count1 = 0;
    let count2 = 0;

    // Check pattern starting with 0: 010101...
    for (let i = 0; i < n; i++) {
        if (i % 2 === 0) {
            if (s[i] !== '0') count1++;
        } else {
            if (s[i] !== '1') count1++;
        }
    }

    // Check pattern starting with 1: 101010...
    for (let i = 0; i < n; i++) {
        if (i % 2 === 0) {
            if (s[i] !== '1') count2++;
        } else {
            if (s[i] !== '0') count2++;
        }
    }

    return Math.min(count1, count2);
};

class Solution:
