        int currentLength = 0;

        for (const string& word : words) {
            if (currentLength + word.length() + currentLine.size() > maxWidth) {
                int totalSpaces = maxWidth - currentLength;
                int gaps = currentLine.size() - 1;

                if (gaps == 0) {
                    result.push_back(currentLine[0] + string(totalSpaces, ' '));
                } else {
                    int spacePerGap = totalSpaces / gaps;
                    int extraSpaces = totalSpaces % gaps;
                    string line;

                    for (int i = 0; i < currentLine.size(); i++) {
                        line += currentLine[i];
                        if (i < gaps) {
                            line += string(spacePerGap + (i < extraSpaces ? 1 : 0), ' ');
                        }
                    }
                    result.push_back(line);
                }

                currentLine.clear();
                currentLength = 0;
            }

            currentLine.push_back(word);
            currentLength += word.length();
        }

        // Handle last line
        string lastLine;
        for (const string& word : currentLine) {
            if (!lastLine.empty()) lastLine += ' ';
            lastLine += word;
        }
        lastLine += string(maxWidth - lastLine.length(), ' ');
        result.push_back(lastLine);

        return result;
    }
};

